var _HomeComponent = class _HomeComponent {
  constructor(http, toaster, dialog, renderer, el) {
    this.http = http;
    this.toaster = toaster;
    this.dialog = dialog;
    this.renderer = renderer;
    this.el = el;
    this.FileUploadUrl = "http://10.100.102.84:5000/api/Filter/Filter";
    this.flag = true;
    this.success = false;
    this.error = false;
    this.errorMessage = "";
    this.alertType = "";
  }
  ngOnInit() {
  }
  selectfile(event) {
    this.file = event.target.files[0];
    console.log(this.file);
  }
  upload() {
    if (!this.file) {
      this.toaster.error("No file selected!");
      return;
    }
    let formData = new FormData();
    formData.append("file", this.file);
    this.flag = false;
    this.http.post(this.FileUploadUrl, formData).subscribe((data) => {
      console.log(data);
      this.flag = true;
      this.toaster.success("Update is Done");
      setTimeout(() => {
        this.showStyledAlert(data);
      }, 1e3);
    }, (error) => {
      const errorMessage = error.error || "An error occurred during update.";
      this.errorMessage = errorMessage;
      this.error = true;
      this.toaster.error("Error during upload:", errorMessage, { disableTimeOut: true });
      this.flag = true;
    });
  }
  formatDataToHTML(data) {
    let message = "";
    for (const key in data) {
      if (data.hasOwnProperty(key)) {
        message += `<strong>${key}:</strong> ${data[key]}<br>`;
      }
    }
    return message;
  }
  showStyledAlert(data) {
    const alertMessage = this.formatDataToHTML(data);
    const config3 = {
      closeButton: true,
      // Show close button
      progressBar: true,
      // Show progress bar
      toastClass: "ngx-toastr custom-toast",
      // Apply custom CSS class for the toastr message
      positionClass: "toast-top-center",
      // Set position of the toastr message
      enableHtml: true,
      // Enable HTML content in the toastr message
      disableTimeOut: true
      // Do not automatically close
    };
    this.toaster.show(alertMessage, "Data Received", config3);
  }
};
